import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    X = int(input_data[0])
    K = int(input_data[1])
    D = int(input_data[2])

    # Move towards zero as much as possible
    if X > 0:
        steps = X // D
    else:
        steps = (-X) // D

    if steps >= K:
        # We can reach zero or cross it within K moves
        # The best we can do is move K steps towards zero
        if X > 0:
            ans = X - K * D
        else:
            ans = X + K * D
        print(abs(ans))
    else:
        # We can reach the closest point to zero and still have moves left
        remaining = K - steps
        # After 'steps' moves, we are at the closest point to zero (or crossed it)
        # If remaining is even, we can oscillate and stay at that point
        # If remaining is odd, we must move one step away from zero
        if remaining % 2 == 0:
            # Calculate the coordinate after 'steps' moves
            if X > 0:
                coord = X - steps * D
            else:
                coord = X + steps * D
            print(abs(coord))
        else:
            # Move one more step towards zero (which might cross zero)
            if X > 0:
                coord = X - (steps + 1) * D
            else:
                coord = X + (steps + 1) * D
            print(abs(coord))

if __name__ == "__main__":
    solve()
